// Summarize today's sales
const rows = $input.all();
const today = new Date().toISOString().slice(0, 10);

let totalOrder = 0;
let totalRevenue = 0;
let totalItem = 0;
const perProduct = {};

for (const r of rows) {
  const j = r.json;
  const date = String(j['Date'] || j['date'] || '').slice(0, 10);
  if (date !== today) continue;

  totalOrder++;
  const total = Number(j['Total'] || j['total'] || 0);
  totalRevenue += total;
  const qty = Number(j['Qty'] || j['qty'] || 1);
  totalItem += qty;

  const product = String(j['Product'] || j['product'] || 'Other');
  if (!perProduct[product]) perProduct[product] = { qty: 0, revenue: 0 };
  perProduct[product].qty += qty;
  perProduct[product].revenue += total;
}

const rupiah = n => 'Rp ' + Number(n).toLocaleString('id-ID');

let message = '📊 DAILY SALES REPORT\n';
message += 'Date: ' + today + '\n';
message += '━━━━━━━━━━━━━━━━━━\n\n';
message += '🛒 Total Orders  : ' + totalOrder + '\n';
message += '📦 Total Items   : ' + totalItem + '\n';
message += '💰 Total Revenue : ' + rupiah(totalPendapatan) + '\n\n';

if (Object.keys(perProduct).length > 0) {
  message += '📌 PRODUCTS SOLD\n';
  const sorted = Object.entries(perProduct).sort((a, b) => b[1].revenue - a[1].revenue);
  for (const [name, d] of sorted) {
    message += '• ' + name + ' — ' + d.qty + ' pcs (' + rupiah(d.revenue) + ')\n';
  }
} else {
  message += 'No orders yet today.';
}

return [{ json: { report: message, total_order: totalOrder, total_revenue: totalRevenue } }];
